#!/usr/bin/env bash
set -euo pipefail
here=$(cd "$(dirname "$0")" && pwd)
: "${MATHLIB_DIR:?Path to built Mathlib at the pinned revision}"
lib=$(cd "$MATHLIB_DIR" && pwd)
lean=${LEAN_BIN:-lean}
[[ $(git -C "$lib" rev-parse HEAD) == d13f23b723b8a846827a245b89c10fc7d3f11612 ]]
"$lean" --version | grep -F 'version 4.34.1'
(cd "$here" && sha256sum -c SHA256SUMS)
out=$(mktemp -d)
trap 'rm -rf "$out"' EXIT
export LEAN_PATH="$out:$lib/.lake/build/lib/lean:$(find "$lib/.lake/packages" -type d -path '*/.lake/build/lib/lean' | paste -sd ':' -)"
for n in RobustFolkman MixedCorners ParagliderCayley GeometricGraphEdit GeometricMoment GeometricAssembly GeometricWindow GeometricPatterns GramLowOrder GramCoefficients GeometricGap GeometricHGram GeometricVariance GeometricTriangleOverlap GeometricConditioning GeometricChargeMoment GeometricChargeGraph GeometricChargeCount GeometricTriangleCount GeometricPatternAssembly GeometricAttachment GeometricSchurLocal GeometricNearIdentity GeometricLocalize GeometricAnchorBox GeometricDetLower GeometricProbe GeometricSaturated GeometricCompact GeometricExactScalar GeometricPage GeometricPageTransfer GeometricDiamond GeometricForbidden GeometricPatternDet GeometricRateWindow GeometricGraphMeasure GeometricUniformSphere GeometricPatternMeasure GeometricMarginals GeometricRotations GeometricSphereTransitive GeometricRootTriangle GeometricSharedRoot GeometricLaplaceBounds GeometricStrictGram GeometricChart GeometricChartVolume GeometricNormalization GeometricLogBounds GeometricNormalizedRate GeometricProjectionJacDet GeometricProjectionDerivative GeometricProjectionInverse GeometricProjectionChange GeometricConeRatio GeometricRadialIntegration GeometricResidualSplit GeometricProjectionFubini GeometricProjectionProduct GeometricAngularIntegration GeometricSphericalProjection GeometricProjectionLaw GeometricLinearProjection GeometricAnchorCoordinates GeometricAnchorDensity GeometricGramTelescope GeometricSphereTransport GeometricSpanProjection GeometricSpanAnchors GeometricGramConditional GeometricFixedAnchors GeometricSphereNull GeometricIIDAnchor GeometricGramBorder GeometricGramChartStep GeometricChartBorder GeometricSampleChart GeometricChartWeight GeometricChartConditional GeometricProjectionMass GeometricGramFiber GeometricJointGram GeometricJointGramNormalized GeometricSpherePatternRate GeometricActualRate GeometricDimensionScaling GeometricPowerRates GeometricFailurePowers GeometricPatternReindex GeometricMomentBounds GeometricCommonRates GeometricQuantitativeAssembly GeometricLabelShapes GeometricMomentEvents GeometricForbiddenLabels GeometricChargeEvents GeometricTriangleLabels GeometricDiamondEvents GeometricTrianglePacking GeometricRootOverlap GeometricDisjointOverlap GeometricTriangleCorr GeometricFolkmanConditional GeometricFolkmanReduction GeometricLinkCorners GeometricLinkMargin GeometricActualLinks GeometricLinkCuts GeometricQuadraticCuts GeometricNormalizedCut GeometricDirectedLinkSum GeometricSpectralInterface GeometricProductConditioning GeometricRootCap GeometricCapMass GeometricCapSelection GeometricCapCount GeometricWeightedLinks GeometricWeightedMoment GeometricWeightedFailure GeometricRootedCount GeometricRootedVariance GeometricRootedSecond GeometricRootedRates GeometricRootedPower GeometricRelativeLinks GeometricTypicalLink GeometricTypicalFolkman GeometricCutTransfer GeometricTriangleShell GeometricShellWeight GeometricShellIntegral GeometricShellTail GeometricTripleChart GeometricExcessChart GeometricActualShell GeometricActualShellBound GeometricShellLoss GeometricThinShellBracket GeometricResidualIndependence GeometricShellDirection GeometricBandResidualLaw GeometricBandEdges GeometricRootTransport GeometricDecoupling GeometricRootedExcess GeometricRootedShellLoss GeometricDecoupledNorm GeometricSliceWeight GeometricCenteredCut GeometricSliceMass GeometricHeightDensity GeometricSliceCompare GeometricShiftedRate GeometricSphericalCompare GeometricResidualDegree GeometricShellParameter GeometricRankOneVariance GeometricOperatorOrder GeometricColumnGram GeometricPairMoment GeometricShellMarkov GeometricKernelCovariance GeometricPopulationPower GeometricSphereIsotropy GeometricSphereGrid GeometricGridApprox GeometricPlaneReflection GeometricPlaneCoupling GeometricCapTangentMoment GeometricCapHeightTail GeometricCapHeightMoment GeometricCapCoupling GeometricCapLipschitz GeometricCapKernel GeometricCapAveraging GeometricCapLipEnergy GeometricSphericalStrip GeometricCapSmoothing GeometricPopulationL2 GeometricCenteredEnergy GeometricCenteredKernelL2 GeometricCapQuadratic GeometricKernelPerturbation GeometricGridEnergyLift GeometricFiniteGridIntegral GeometricFiniteGridMeasurable GeometricGridQuadratic GeometricPairStrip GeometricGridOperator GeometricQuantizedCap GeometricSparseBernoulliTail GeometricConditionalRowTail GeometricRowNorm GeometricSampleQuantization GeometricGridRateLower GeometricGridResolution GeometricGridRowMass GeometricKernelBernoulli GeometricQuantizedLaw GeometricTrimmedColumns GeometricCrossOperator GeometricDecoupledTail GeometricMatrixReindex GeometricBlockSampling GeometricSampleCut GeometricCapGapEventual GeometricBandBadMixture GeometricBandCountLower GeometricSampleAsymptotic GeometricShellBudget GeometricCapProbability GeometricBandPairLaw GeometricPairGraphs GeometricBandShellPair GeometricBandLift GeometricShellRemoval GeometricGraphLossTail GeometricRootedSample GeometricShellScales GeometricShellDimension GeometricPairGraphMeasure GeometricRootShellTransfer GeometricShellSmallLoss; do
  cap=2850; case "$n" in Geometric*Measure|GeometricUniformSphere|GeometricMarginals|GeometricRotations|GeometricSphereTransitive|GeometricRootTriangle|GeometricSharedRoot|GeometricLaplaceBounds|GeometricStrictGram|GeometricChart|GeometricChartVolume|GeometricNormalization|GeometricLogBounds|GeometricNormalizedRate|GeometricProjectionJacDet|GeometricProjectionDerivative|GeometricProjectionInverse|GeometricProjectionChange|GeometricConeRatio|GeometricRadialIntegration|GeometricResidualSplit|GeometricProjectionFubini|GeometricProjectionProduct|GeometricAngularIntegration|GeometricSphericalProjection|GeometricProjectionLaw|GeometricLinearProjection|GeometricAnchorCoordinates|GeometricAnchorDensity|GeometricGramTelescope|GeometricSphereTransport|GeometricSpanProjection|GeometricSpanAnchors|GeometricGramConditional|GeometricFixedAnchors|GeometricSphereNull|GeometricIIDAnchor|GeometricGramBorder|GeometricGramChartStep|GeometricChartBorder|GeometricSampleChart|GeometricChartWeight|GeometricChartConditional|GeometricProjectionMass|GeometricGramFiber|GeometricJointGram|GeometricJointGramNormalized|GeometricSpherePatternRate|GeometricActualRate|GeometricDimensionScaling|GeometricPowerRates|GeometricFailurePowers|GeometricPatternReindex|GeometricMomentBounds|GeometricCommonRates|GeometricQuantitativeAssembly|GeometricLabelShapes|GeometricMomentEvents|GeometricForbiddenLabels|GeometricChargeEvents|GeometricTriangleLabels|GeometricDiamondEvents|GeometricTrianglePacking|GeometricRootOverlap|GeometricDisjointOverlap|GeometricTriangleCorr|GeometricFolkmanConditional|GeometricFolkmanReduction|GeometricLinkCorners|GeometricLinkMargin|GeometricActualLinks|GeometricLinkCuts|GeometricQuadraticCuts|GeometricNormalizedCut|GeometricDirectedLinkSum|GeometricSpectralInterface|GeometricProductConditioning|GeometricRootCap|GeometricCapMass|GeometricCapSelection|GeometricCapCount|GeometricWeightedLinks|GeometricWeightedMoment|GeometricWeightedFailure|GeometricRootedCount|GeometricRootedVariance|GeometricRootedSecond|GeometricRootedRates|GeometricRootedPower|GeometricRelativeLinks|GeometricTypicalLink|GeometricTypicalFolkman|GeometricCutTransfer|GeometricTriangleShell|GeometricShellWeight|GeometricShellIntegral|GeometricShellTail|GeometricTripleChart|GeometricExcessChart|GeometricActualShell|GeometricActualShellBound|GeometricShellLoss|GeometricThinShellBracket|GeometricResidualIndependence|GeometricShellDirection|GeometricBandResidualLaw|GeometricBandEdges|GeometricRootTransport|GeometricDecoupling|GeometricRootedExcess|GeometricRootedShellLoss|GeometricDecoupledNorm|GeometricSliceWeight|GeometricCenteredCut|GeometricSliceMass|GeometricHeightDensity|GeometricSliceCompare|GeometricShiftedRate|GeometricSphericalCompare|GeometricResidualDegree|GeometricShellParameter|GeometricRankOneVariance|GeometricOperatorOrder|GeometricColumnGram|GeometricPairMoment|GeometricShellMarkov|GeometricKernelCovariance|GeometricPopulationPower|GeometricSphereIsotropy|GeometricSphereGrid|GeometricGridApprox|GeometricPlaneReflection|GeometricPlaneCoupling|GeometricCapTangentMoment|GeometricCapHeightTail|GeometricCapHeightMoment|GeometricCapCoupling|GeometricCapLipschitz|GeometricCapKernel|GeometricCapAveraging|GeometricCapLipEnergy|GeometricSphericalStrip|GeometricCapSmoothing|GeometricPopulationL2|GeometricCenteredEnergy|GeometricCenteredKernelL2|GeometricCapQuadratic|GeometricKernelPerturbation|GeometricGridEnergyLift|GeometricFiniteGridIntegral|GeometricFiniteGridMeasurable|GeometricGridQuadratic|GeometricPairStrip|GeometricGridOperator|GeometricQuantizedCap|GeometricSparseBernoulliTail|GeometricConditionalRowTail|GeometricRowNorm|GeometricSampleQuantization|GeometricGridRateLower|GeometricGridResolution|GeometricGridRowMass|GeometricKernelBernoulli|GeometricQuantizedLaw|GeometricTrimmedColumns|GeometricCrossOperator|GeometricDecoupledTail|GeometricMatrixReindex|GeometricBlockSampling|GeometricSampleCut|GeometricCapGapEventual|GeometricBandBadMixture|GeometricBandCountLower|GeometricSampleAsymptotic|GeometricShellBudget|GeometricCapProbability|GeometricBandPairLaw|GeometricPairGraphs|GeometricBandShellPair|GeometricBandLift|GeometricShellRemoval|GeometricGraphLossTail|GeometricRootedSample|GeometricShellScales|GeometricShellDimension|GeometricPairGraphMeasure|GeometricRootShellTransfer|GeometricShellSmallLoss) cap=4100;; esac
  "$lean" -j1 -M"$cap" --root="$here" -o "$out/$n.olean" "$here/$n.lean"
done

# Optional concentration proof, using only the exact audited upstream sources.
if [[ -n ${SLT_V432_DIR:-} ]]; then
  slt=$(cd "$SLT_V432_DIR" && pwd)
  (cd "$slt" && sha256sum -c "$here/SLT-SOURCE-SHA256.txt")
  src="$out/slt-source"
  libout="$out/slt-compiled"
  export LEAN_PATH="$libout:$LEAN_PATH"
  for f in SLT/MatrixInfra/Basic SLT/MatrixInfra/CourantFischer SLT/MatrixInfra/MatCalc SLT/RMT/Lieb SLT/RMT/MatBern; do
    mkdir -p "$src/$(dirname "$f")" "$libout/$(dirname "$f")"
    cp "$slt/$f.lean" "$src/$f.lean"
  done
  patch --directory="$src" --strip=1 --fuzz=0 --batch --forward < "$here/SLT-v432-to-mathlib434.patch"
  for f in SLT/MatrixInfra/Basic SLT/MatrixInfra/CourantFischer SLT/MatrixInfra/MatCalc SLT/RMT/Lieb SLT/RMT/MatBern; do
    "$lean" -j1 -M5100 --root="$src" -o "$libout/$f.olean" "$src/$f.lean"
  done
  for n in GeometricFiniteBernstein GeometricIIDBernstein GeometricCrossBernstein GeometricRectangleTail GeometricRectangleRates GeometricUniformRectangle GeometricRoundedSample GeometricRoundedFinite GeometricRoundedGrid GeometricActualSampleNorm GeometricActualSampleCut GeometricSphereSampleTransfer GeometricRetainedGraph GeometricShellSample GeometricFolkmanUnconditional; do
    "$lean" -j1 -M5100 --root="$here" -o "$out/$n.olean" "$here/$n.lean"
  done
fi
